import{_ as e,C as i,c as t,o as r,a0 as n,b as l,w as a,a as s,G as o,a1 as u}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Camp d&#39;entraînement : Guide du week-end","description":"","frontmatter":{},"headers":[],"relativePath":"fr/training-camp.md","filePath":"fr/training-camp.md"}');const p=e({name:"fr/training-camp.md"},[["render",function(e,d,p,c,m,g){const h=i("Mermaid");return r(),t("div",null,[d[2]||(d[2]=n('<h1 id="camp-d-39-entrainement-guide-du-week-end" tabindex="-1">Camp d&#39;entraînement : Guide du week-end <a class="header-anchor" href="#camp-d-39-entrainement-guide-du-week-end" aria-label="Permalink to &quot;Camp d&amp;#39;entraînement : Guide du week-end&quot;">​</a></h1><h2 id="comment-organiser-un-camp-d-39-entrainement-de-fin-de-semaine-pour-10-a-20-joueurs" tabindex="-1">Comment organiser un camp d&#39;entraînement de fin de semaine pour 10 à 20 joueurs <a class="header-anchor" href="#comment-organiser-un-camp-d-39-entrainement-de-fin-de-semaine-pour-10-a-20-joueurs" aria-label="Permalink to &quot;Comment organiser un camp d&amp;#39;entraînement de fin de semaine pour 10 à 20 joueurs&quot;">​</a></h2><p>Ce guide complet vous aide à organiser et à animer un stage d&#39;entraînement de week-end alliant théorie, pratique et compétition. Mettez en application sur les pistes les notions de préparation mentale présentées sur ce site pour un impact maximal.</p><div class="tip custom-block"><p class="custom-block-title">La philosophie du camp d&#39;entraînement</p><p>La théorie sans pratique n&#39;est que de l&#39;information. La pratique sans théorie n&#39;est que répétition. La compétition sans réflexion n&#39;est que jeu. Ce week-end intègre ces trois éléments pour un apprentissage transformateur.</p></div>',4)),(r(),l(u,null,{default:a(()=>[o(h,{id:"mermaid-14",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWeekend%20Camp%5D%20--%3E%20B%5BFriday%3A%20Theory%5D%0A%20%20%20%20B%20--%3E%20C%5BSaturday%3A%20Practice%5D%0A%20%20%20%20C%20--%3E%20D%5BSunday%3A%20Competition%5D%0A%20%20%20%20D%20--%3E%20E%5BIntegration%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:a(()=>[...d[0]||(d[0]=[s(" Loading... ",-1)])]),_:1})),d[3]||(d[3]=n('<h2 id="planification-avant-le-camp" tabindex="-1">Planification avant le camp <a class="header-anchor" href="#planification-avant-le-camp" aria-label="Permalink to &quot;Planification avant le camp&quot;">​</a></h2><h3 id="taille-et-structure-du-groupe" tabindex="-1">Taille et structure du groupe <a class="header-anchor" href="#taille-et-structure-du-groupe" aria-label="Permalink to &quot;Taille et structure du groupe&quot;">​</a></h3><p><strong>Nombre optimal :</strong> 10 à 20 joueurs</p><ul><li><strong>Petit camp (10-12) :</strong> Partage plus intime et plus profond</li><li><strong>Grand camp (16-20) :</strong> Perspectives plus diversifiées, nécessite des sous-groupes</li></ul><p><strong>Structure de l&#39;équipe :</strong></p><ul><li>Divisez-vous en équipes de 3 ou 4 pour l&#39;entraînement et la compétition.</li><li>Mélanger les niveaux de compétence et les styles de jeu</li><li>Faire tourner les équipes tout au long du week-end</li></ul><h3 id="besoins-en-personnel" tabindex="-1">Besoins en personnel <a class="header-anchor" href="#besoins-en-personnel" aria-label="Permalink to &quot;Besoins en personnel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rôle</th><th>Responsabilités</th><th>Quantité</th></tr></thead><tbody><tr><td><strong>Coordonnateur de la performance mentale</strong></td><td>Animer des séances théoriques et des ateliers de dynamique de groupe</td><td>1</td></tr><tr><td><strong>Entraîneur technique</strong></td><td>Superviser les entraînements, fournir des commentaires</td><td>1-2</td></tr><tr><td><strong>Directeur de compétition</strong></td><td>Organisation du tournoi, gestion logistique</td><td>1</td></tr><tr><td><strong>Personnel de soutien</strong></td><td>Repas, installation, administration</td><td>1-2</td></tr></tbody></table><h3 id="exigences-relatives-a-l-39-emplacement" tabindex="-1">Exigences relatives à l&#39;emplacement <a class="header-anchor" href="#exigences-relatives-a-l-39-emplacement" aria-label="Permalink to &quot;Exigences relatives à l&amp;#39;emplacement&quot;">​</a></h3><p>::: informations sur les besoins en installations <strong>Piste:</strong></p><ul><li>Terrains multiples (minimum 3-4 pistes)</li><li>Différentes surfaces si possible (gravier, sable, dur)</li><li>Éclairage pour les jeux du soir</li></ul><p><strong>Espace intérieur :</strong></p><ul><li>Salle pouvant accueillir 20 personnes en cercle (séances théoriques)</li><li>Séparé de la piste</li><li>Tableau blanc/projecteur</li><li>Sièges confortables</li></ul><p><strong>Hébergement:</strong></p><ul><li>Sur place ou à proximité (à distance de marche)</li><li>Les chambres partagées favorisent les liens.</li><li>Un espace calme pour la réflexion</li></ul><p><strong>Restauration:</strong></p><ul><li>Repas axés sur la nutrition (voir <a href="./food">Guide alimentaire</a>)</li><li>Évitez les hypoglycémies.</li><li>Points d&#39;hydratation :::</li></ul><h3 id="liste-de-verification-du-materiel" tabindex="-1">Liste de vérification du matériel <a class="header-anchor" href="#liste-de-verification-du-materiel" aria-label="Permalink to &quot;Liste de vérification du matériel&quot;">​</a></h3><details class="details custom-block"><summary>Liste complète des matériaux</summary><p><strong>Séances théoriques :</strong></p><ul><li>[ ] Chaises pour le cercle (pas de tables)</li><li>[ ] Boules et cochonnet pour centre</li><li>[ ] Tableaux de conférence et marqueurs</li><li>[ ] Notes autocollantes</li><li>[ ] Fiches de travail (Manuel d&#39;utilisation, Critique intérieure, etc.)</li><li>[ ] Papier et stylos</li><li>[ ] Projecteur (pour le contenu du site web)</li></ul><p><strong>Séances d&#39;entraînement :</strong></p><ul><li>[ ] Mètre ruban</li><li>[ ] Cônes/marqueurs pour les exercices</li><li>[ ] Caméra vidéo/trépied</li><li>[ ] Bloc-notes et papier (suivi)</li><li>[ ] Siffler</li></ul><p><strong>Concours:</strong></p><ul><li>[ ] Feuilles de score</li><li>[ ] Tableau du tournoi</li><li>[ ] Prix/reconnaissance</li><li>[ ] Trousse de premiers secours</li></ul><p><strong>Logistique:</strong></p><ul><li>[ ] Étiquettes nominatives</li><li>[ ] Liste des participants avec leurs contacts</li><li>[ ] Informations de contact d&#39;urgence</li><li>[ ] Bouteilles d&#39;eau</li><li>[ ] Crème solaire</li><li>[ ] Mouchoirs (pour le travail émotionnel !)</li></ul></details><h2 id="programme-du-week-end" tabindex="-1">Programme du week-end <a class="header-anchor" href="#programme-du-week-end" aria-label="Permalink to &quot;Programme du week-end&quot;">​</a></h2><h3 id="vendredi-soir-3-heures" tabindex="-1">Vendredi soir (3 heures) <a class="header-anchor" href="#vendredi-soir-3-heures" aria-label="Permalink to &quot;Vendredi soir (3 heures)&quot;">​</a></h3><p><strong>18h00-18h30 - Arrivée et accueil</strong></p><ul><li>Enregistrement</li><li>Attribution des chambres</li><li>Aperçu du week-end</li></ul><p><strong>18h30-19h30 - Dîner</strong></p><ul><li>Repas axé sur la nutrition</li><li>Présentations informelles</li></ul><p><strong>19h30-22h30 - Séance théorique : Fondements</strong></p><p>Utilisez le <a href="./workshop">guide d&#39;atelier</a> pour une facilitation détaillée :</p><ol><li><strong>Règles de base (15 min)</strong> - Établir un climat de sécurité psychologique</li><li><strong>Matrice de pointage (20 min)</strong> - Évaluation de l&#39;énergie du groupe</li><li><strong>L&#39;iceberg (30 min)</strong> - Explorez vos pensées intérieures</li><li><strong>Manuel d&#39;utilisation (45 min)</strong> - Développer la compréhension de l&#39;équipe</li><li><strong>La peur dans un chapeau (45 min)</strong> - Rompre l&#39;isolement</li><li><strong>Fin de session (15 min)</strong> - Boucler la boucle</li></ol><p><strong>22h30 - Temps libre</strong></p><ul><li>Socialisation informelle</li><li>Repos et réflexion</li></ul>',30)),(r(),l(u,null,{default:a(()=>[o(h,{id:"mermaid-437",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFriday%20Theory%5D%20--%3E%20B%5BPsychological%20Safety%5D%0A%20%20%20%20B%20--%3E%20C%5BSelf-Awareness%5D%0A%20%20%20%20C%20--%3E%20D%5BTeam%20Understanding%5D%0A%20%20%20%20D%20--%3E%20E%5BReady%20for%20Practice%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A"})]),fallback:a(()=>[...d[1]||(d[1]=[s(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=n('<h3 id="samedi-journee-complete-theorie-pratique" tabindex="-1">Samedi (Journée complète - Théorie + Pratique) <a class="header-anchor" href="#samedi-journee-complete-theorie-pratique" aria-label="Permalink to &quot;Samedi (Journée complète - Théorie + Pratique)&quot;">​</a></h3><p><strong>08:00-09:00 - Petit-déjeuner et pleine conscience</strong></p><ul><li>Petit-déjeuner tranquille</li><li>Méditation guidée facultative de 15 minutes</li><li>Définissez vos intentions pour la journée</li></ul><p><strong>09:00-10:30 - Séance théorique : Relier le contenu à l&#39;expérience</strong></p><p>Choisissez 3 ou 4 sujets sur le site web de l&#39;Académie et explorez le jeu intérieur :</p><p><strong>Exemples de sujets :</strong></p><ol><li><p><strong><a href="./education/nutrition/">Nutrition</a></strong> (20 min)</p><ul><li>« Comment vos choix alimentaires changent-ils sous la pression ? »</li><li>« Mangez-vous ce dont votre corps a besoin ou ce que votre anxiété réclame ? »</li><li>Entraînement : Planifiez votre nutrition pour le jour de la compétition</li></ul></li><li><p><strong><a href="./education/mental-strength/">Force mentale</a></strong> (25 min)</p><ul><li>« Quel est votre rapport à l&#39;échec ? »</li><li>« Comment se parle-t-on à soi-même après un échec ? »</li><li>Activité : Transformer son critique intérieur en coach intérieur</li></ul></li><li><p><strong>[Pleine conscience](./éducation/pleine conscience/)</strong> (25 min)</p><ul><li>« Où va votre esprit pendant la pause avant de lancer ? »</li><li>« Qu’est-ce qui vous fait sortir du moment présent ? »</li><li>Exercice : scan corporel de 5 minutes</li></ul></li><li><p><strong><a href="./education/tactics/">Tactiques</a></strong> (20 min)</p><ul><li>«Votre choix de tir est-il basé sur une stratégie ou sur la peur ?»</li><li>«Quand faut-il privilégier la sécurité plutôt que la prise de risques ?»</li><li>Discussion : Profils de risque au sein du groupe</li></ul></li></ol><p><strong>10h30-10h45 - Pause</strong></p><p><strong>10:45-12:30 - Intégration sur piste : Exercices de concentration mentale</strong></p><p><strong>Exercice 1 : Annoncez votre tir (30 min)</strong></p><p>Extrait du <a href="./workshop">guide d&#39;atelier</a> - pratiquez la prise en charge de vos intentions et de vos doutes :</p><ol><li>Annoncez la cible : « Je tire sur le fer »</li><li>Indiquez votre niveau de confiance : « Je suis à 7 sur 10 »</li><li>Nommez la pensée intérieure : « Ma voix intérieure s&#39;inquiète de l&#39;effet rétroactif. »</li><li>Exécutez le tir</li><li>Réfléchissez : « Que s&#39;est-il passé ? Qu&#39;avez-vous appris ? »</li></ol><p><strong>Exercice 2 : Interférence cognitive (30 min)</strong></p><p>Vérifier si la technique est devenue automatique :</p><ul><li>Le coordinateur pose des questions complexes pendant que le joueur tire.</li><li>« Nommez 5 capitales » ou « Comptez à rebours à partir de 100 en soustrayant 7 à chaque fois ».</li><li>Le succès repose sur une technique implicite, non consciemment mise en œuvre.</li></ul><p><strong>Exercice 3 : Mise en pratique du manuel d&#39;utilisation (30 min)</strong></p><p>Appliquer les manuels d&#39;utilisation à partir de vendredi :</p><ul><li>Jouez par équipes de 3 Après chaque tir, les coéquipiers réagissent conformément au manuel d&#39;utilisation. « Marc a besoin de silence après un échec » - l&#39;équipe respecte cela.</li><li>Débriefing : « Qu&#39;avez-vous ressenti en étant compris ? »</li></ul><p><strong>12h30-14h00 - Déjeuner et repos</strong></p><ul><li>Repas axé sur la nutrition</li><li>Un moment de calme pour la réflexion</li><li>Facultatif : entretiens individuels avec le coordinateur</li></ul><p><strong>14h00-17h00 - Séance d&#39;entraînement : Adaptation au terrain</strong></p><p><strong>Objectif :</strong> Développer l&#39;adaptabilité et la flexibilité mentale</p><p><strong>Installation:</strong></p><ul><li>Rotation à travers 3-4 terrains/pistes différents</li><li>45 minutes par terrain</li><li>Concentrez-vous sur l&#39;adaptation mentale, et pas seulement technique.</li></ul><p><strong>Structure de rotation :</strong></p><table tabindex="0"><thead><tr><th>Terrain</th><th>Concentration mentale</th><th>Pratique</th></tr></thead><tbody><tr><td><strong>Terrain 1 : Sol meuble/sableux</strong></td><td>Acceptation de l&#39;incertitude</td><td>« La donnée - accepter ce qui est »</td></tr><tr><td><strong>Terrain 2 : Dur/Gravier</strong></td><td>Précision sous pression</td><td>« Faites confiance à votre technique »</td></tr><tr><td><strong>Terrain 3 : Inégal</strong></td><td>Régulation émotionnelle</td><td>« Restez calme face à l&#39;injustice »</td></tr><tr><td><strong>Terrain 4 : Compétition</strong></td><td>Accès à l’état de flow</td><td>« Trouvez la zone »</td></tr></tbody></table><p><strong>Facilitation :</strong></p><ul><li>L&#39;entraîneur technique fournit des commentaires sur la technique</li><li>MPC demande : « À quoi pensez-vous en ce moment ? »</li><li>Journal des joueurs entre les rotations</li></ul><p><strong>17h00-18h00 - Pause et réflexion</strong></p><ul><li>Journal individuel</li><li>« Qu&#39;as-tu appris sur toi-même aujourd&#39;hui ? »</li><li>« Qu&#39;est-ce que tu feras différemment demain ? »</li></ul><p><strong>18h00-19h00 - Dîner</strong></p><p><strong>19h00-21h00 - Théorie du soir : Vulnérabilité profonde</strong></p><p><strong>Activité 1 : Recadrer le critique intérieur (45 min)</strong></p><p>Consultez le <a href="./workshop">guide de l&#39;atelier</a> pour le protocole complet :</p><ol><li>Identifiez la phrase critique exacte.</li><li>Repenser comme un coach intérieur</li><li>Cabinet partenaire</li></ol><p><strong>Activité 2 : Préparation à la compétition (45 min)</strong></p><p>Demain, c&#39;est le jour de la compétition. Préparez-vous mentalement :</p><ol><li><p><strong>Visualisation (15 min)</strong> Fermez les yeux</p><ul><li>Imaginez le tir parfait</li><li>Ressentez la confiance</li><li>Remarquez le calme</li></ul></li><li><p><strong>Protocoles d&#39;équipe (20 min)</strong></p><ul><li>Créer des signaux de soutien</li><li>&quot;J&#39;ai besoin d&#39;une réinitialisation&quot; = toucher des boules</li><li>« J&#39;ai besoin d&#39;encouragements » = check du poing</li><li>« J&#39;ai besoin d&#39;espace » = reculer</li></ul></li><li><p><strong>Définir ses intentions (10 min)</strong></p><ul><li>« Demain, je me concentrerai sur… »</li><li>« Mon but n&#39;est pas de gagner, mais de… »</li><li>« Je vais m&#39;entraîner… »</li></ul></li></ol><p><strong>Départ (30 min)</strong></p><ul><li>Partagez une de vos craintes concernant demain</li><li>Partager une intention</li><li>Soutien du groupe</li></ul><p><strong>21h00 - Temps libre</strong></p><ul><li>Au lit tôt (compétition demain !)</li><li>Réflexion silencieuse</li></ul><h3 id="dimanche-jour-de-competition" tabindex="-1">Dimanche (Jour de compétition) <a class="header-anchor" href="#dimanche-jour-de-competition" aria-label="Permalink to &quot;Dimanche (Jour de compétition)&quot;">​</a></h3><p><strong>08h00-09h00 - Petit-déjeuner et préparation mentale</strong></p><ul><li>Petit-déjeuner léger (voir <a href="./education/nutrition/">Guide nutritionnel</a>)</li><li>15 minutes de pratique de la pleine conscience</li><li>Réunions d&#39;équipe</li></ul><p><strong>09:00-09:30 - Briefing sur la concurrence</strong></p><p><strong>Format :</strong> Tournoi toutes rondes</p><ul><li>Équipes de 3</li><li>Jouer jusqu&#39;à 13 points</li><li>Chacun joue contre tout le monde</li><li>Privilégiez le PROCESSUS au résultat</li></ul><p><strong>Le point fort : l&#39;évaluation des performances mentales</strong></p><p>::: astuce Système de double notation <strong>Traditionnel :</strong> Points gagnés <strong>Performances mentales :</strong> Évaluation par MPC</p><p>Points de performance mentale (0 à 5 par match) :</p><ul><li>Outils du manuel d&#39;utilisation utilisés</li><li>A soutenu efficacement ses coéquipiers</li><li>Maîtriser sa critique intérieure</li><li>Rester présent (sans s&#39;attarder sur les images précédentes)</li><li>Sécurité psychologique démontrée</li></ul><p><strong>Gagnant :</strong> Meilleur score combiné (traditionnel + mental) :::</p><p><strong>09:30-13:00 - Compétition du matin</strong></p><ul><li>Jeux toutes rondes</li><li>MPC observe et évalue</li><li>L&#39;entraîneur technique donne un bref retour d&#39;information entre les matchs</li><li>Pauses hydratation et collation</li></ul><p><strong>13h00-14h00 - Déjeuner</strong></p><ul><li>Axé sur la nutrition</li><li>Réflexion informelle</li><li>Repos</li></ul><p><strong>14h00-17h00 - Compétition de l&#39;après-midi</strong></p><ul><li>Continuer le tournoi toutes rondes</li><li>Demi-finales et finales</li><li>Pression croissante</li><li>Mettre en pratique les enseignements du matin</li></ul><p><strong>17h00-17h30 - Remise des prix et reconnaissance</strong></p><p><strong>Catégories :</strong></p><ul><li>Vainqueur traditionnel</li><li>Vainqueur de la performance mentale</li><li>Amélioration la plus importante</li><li>Meilleur coéquipier</li><li>Prix du courage (personnes les plus vulnérables)</li></ul><p><strong>17h30-19h00 - Séance de réflexion finale</strong></p><p><strong>Essentiel :</strong> C&#39;est ici que l&#39;apprentissage se concrétise.</p><p><strong>Structure:</strong></p><p><strong>1. Réflexion individuelle (15 min)</strong> Écrire dans un journal :</p><ul><li>Qu&#39;as-tu appris sur toi-même ce week-end ?</li><li>Qu&#39;est-ce qui vous a surpris ?</li><li>Qu&#39;allez-vous faire différemment ?</li><li>Qu&#39;est-ce que vous emportez chez vous ?</li></ul><p><strong>2. Partage en petits groupes (30 min)</strong> Groupes de 4 à 5 :</p><ul><li>Partager les informations clés</li><li>Qu&#39;est-ce qui a le plus résonné en vous ?</li><li>Qu&#39;est-ce qui a été le plus difficile ?</li><li>Qu&#39;est-ce qui était le plus précieux ?</li></ul><p><strong>3. Intégration complète du groupe (30 min)</strong> Encerclez-vous :</p><ul><li>Chaque personne partage UN point clé à retenir</li><li>MPC valide et connecte les thèmes</li><li>Discussion : « Comment allez-vous appliquer cela ? »</li></ul><p><strong>4. Engagements (15 min)</strong> Chaque personne prend un engagement.</p><ul><li>« Lors de ma prochaine compétition, je vais... »</li><li>Témoins et soutiens du groupe</li></ul><p><strong>5. Clôture (15 min)</strong></p><ul><li>Remercier les participants pour leur courage</li><li>Rappel de la confidentialité</li><li>Échanger des contacts</li><li>Plan de suivi (séance en ligne facultative)</li></ul><p><strong>19h00 - Dîner et départ</strong></p><h2 id="conseils-d-39-animation" tabindex="-1">Conseils d&#39;animation <a class="header-anchor" href="#conseils-d-39-animation" aria-label="Permalink to &quot;Conseils d&amp;#39;animation&quot;">​</a></h2><h3 id="concilier-theorie-et-pratique" tabindex="-1">Concilier théorie et pratique <a class="header-anchor" href="#concilier-theorie-et-pratique" aria-label="Permalink to &quot;Concilier théorie et pratique&quot;">​</a></h3><p>::: Attention à ne pas surcharger la théorie <strong>L&#39;erreur :</strong> Trop de paroles, pas assez d&#39;actions</p><p><strong>Le solde :</strong></p><ul><li>La théorie crée une prise de conscience</li><li>La pratique permet de développer ses compétences</li><li>Intégration des tests de compétition La réflexion consolide l&#39;apprentissage</li></ul><p><strong>Règle générale :</strong> 30 % de théorie, 40 % de pratique, 20 % de compétition, 10 % de réflexion :::</p><h3 id="gestion-de-la-dynamique-de-groupe" tabindex="-1">Gestion de la dynamique de groupe <a class="header-anchor" href="#gestion-de-la-dynamique-de-groupe" aria-label="Permalink to &quot;Gestion de la dynamique de groupe&quot;">​</a></h3><p><strong>L&#39;alpha concurrentiel :</strong></p><ul><li>Veut gagner à tout prix</li><li>Résiste à la vulnérabilité</li><li><strong>Stratégie :</strong> Canaliser la compétitivité dans l&#39;évaluation des performances mentales</li></ul><p><strong>L&#39;observateur silencieux :</strong> Il absorbe tout, sans partager.</p><ul><li><strong>Stratégie :</strong> Créer des points d&#39;entrée à faible enjeu, valider l&#39;observation comme une participation</li></ul><p><strong>Le sceptique :</strong></p><ul><li>« Ces trucs tactiles, ça ne marche pas. »</li><li><strong>Stratégie :</strong> Aïkido verbal - s&#39;aligner et pivoter (voir <a href="./workshop">Guide d&#39;atelier</a>)</li></ul><p><strong>La personne qui partage trop :</strong></p><ul><li>Domine la discussion</li><li><strong>Stratégie :</strong> « Merci, écoutons les autres »</li></ul><h3 id="gerer-les-moments-emotionnels" tabindex="-1">Gérer les moments émotionnels <a class="header-anchor" href="#gerer-les-moments-emotionnels" aria-label="Permalink to &quot;Gérer les moments émotionnels&quot;">​</a></h3><p><strong>Quelqu&#39;un pleure pendant Fear in a Hat :</strong></p><ul><li>✅ Normaliser : « Les larmes sont un signe de courage, pas de faiblesse »</li><li>✅ Proposez un mouchoir, ne vous précipitez pas</li><li>✅ Demandez : « De quoi avez-vous besoin maintenant ? »</li><li>❌ Ne dites pas : « Ça va, ne pleure pas »</li></ul><p><strong>Conflit entre joueurs :</strong></p><ul><li>✅ Pause et adresse</li><li>✅ « Que se passe-t-il en ce moment ? »</li><li>✅ À utiliser comme moment d&#39;apprentissage</li><li>❌ À ne pas faire : ignorer ou minimiser</li></ul><p><strong>Quelqu&#39;un coupe le son :</strong></p><ul><li>✅ Enregistrez-vous en privé pendant la pause</li><li>✅ « J&#39;ai remarqué que tu étais silencieux. Qu&#39;est-ce qui se passe ? »</li><li>✅ Proposez des options : participez différemment, faites une pause</li><li>❌ Ne pas : Dénoncer publiquement</li></ul><h2 id="suivi-post-camp" tabindex="-1">Suivi post-camp <a class="header-anchor" href="#suivi-post-camp" aria-label="Permalink to &quot;Suivi post-camp&quot;">​</a></h2><h3 id="immediat-24-48-heures" tabindex="-1">Immédiat (24-48 heures) <a class="header-anchor" href="#immediat-24-48-heures" aria-label="Permalink to &quot;Immédiat (24-48 heures)&quot;">​</a></h3><p><strong>À envoyer à tous les participants :</strong></p><ul><li>Message de remerciement</li><li>Résumé des points clés Photos du week-end</li><li>Liste de contacts (avec autorisation)</li><li>Lien vers les ressources du site web</li></ul><p><strong>Enregistrements individuels :</strong></p><ul><li>Envoyez un SMS à tous ceux qui ont beaucoup partagé.</li><li>« Comment te sens-tu à l&#39;approche du week-end ? »</li><li>Corriger les éventuels problèmes de vulnérabilité</li></ul><h3 id="court-terme-2-semaines" tabindex="-1">Court terme (2 semaines) <a class="header-anchor" href="#court-terme-2-semaines" aria-label="Permalink to &quot;Court terme (2 semaines)&quot;">​</a></h3><p><strong>Séance en ligne facultative (60 à 90 min) :</strong></p><ul><li>Comment avez-vous mis en pratique vos connaissances ?</li><li>Qu&#39;est-ce qui fonctionne ? Quels sont les défis ?</li><li>Soutien par les pairs et résolution de problèmes</li><li>Renforcer les engagements</li></ul><h3 id="a-long-terme-1-a-3-mois" tabindex="-1">À long terme (1 à 3 mois) <a class="header-anchor" href="#a-long-terme-1-a-3-mois" aria-label="Permalink to &quot;À long terme (1 à 3 mois)&quot;">​</a></h3><p><strong>Participants à l&#39;enquête :</strong></p><ul><li>Qu&#39;est-ce qui est différent dans votre jeu ?</li><li>Quels outils utilisez-vous encore ?</li><li>Qu&#39;est-ce qui permettrait d&#39;améliorer le prochain camp ?</li><li>Le recommanderiez-vous à d&#39;autres ?</li></ul><p><strong>Impact sur la piste :</strong></p><ul><li>Résultats de la compétition</li><li>Confiance auto-déclarée</li><li>Dynamique d&#39;équipe</li><li>Engagement continu</li></ul><h2 id="adaptation-aux-groupes-de-tailles-differentes" tabindex="-1">Adaptation aux groupes de tailles différentes <a class="header-anchor" href="#adaptation-aux-groupes-de-tailles-differentes" aria-label="Permalink to &quot;Adaptation aux groupes de tailles différentes&quot;">​</a></h2><h3 id="petit-camp-10-12-joueurs" tabindex="-1">Petit camp (10-12 joueurs) <a class="header-anchor" href="#petit-camp-10-12-joueurs" aria-label="Permalink to &quot;Petit camp (10-12 joueurs)&quot;">​</a></h3><p><strong>Avantages :</strong></p><ul><li>Un partage plus approfondi</li><li>Une attention plus individualisée</li><li>Des liens plus forts</li></ul><p><strong>Ajustements :</strong></p><ul><li>Un seul groupe pour toute la théorie</li><li>Plus de temps par personne consacré aux activités</li><li>Format de compétition intimiste</li></ul><h3 id="grand-camp-16-20-joueurs" tabindex="-1">Grand camp (16-20 joueurs) <a class="header-anchor" href="#grand-camp-16-20-joueurs" aria-label="Permalink to &quot;Grand camp (16-20 joueurs)&quot;">​</a></h3><p><strong>Avantages :</strong></p><ul><li>Perspectives diverses</li><li>Une plus grande variété de compétitions</li><li>Économies d&#39;échelle</li></ul><p><strong>Ajustements :</strong></p><ul><li>Divisez-vous en 2 groupes pour quelques séances théoriques</li><li>Besoin de 2 MPC/facilitateurs</li><li>Tableau du tournoi plus large</li><li>Des rotations plus structurées</li></ul><h2 id="considerations-budgetaires" tabindex="-1">Considérations budgétaires <a class="header-anchor" href="#considerations-budgetaires" aria-label="Permalink to &quot;Considérations budgétaires&quot;">​</a></h2><h3 id="revenu" tabindex="-1">Revenu <a class="header-anchor" href="#revenu" aria-label="Permalink to &quot;Revenu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Prix par personne</th><th>20 personnes</th><th>10 personnes</th></tr></thead><tbody><tr><td><strong>Inscription</strong></td><td>150-250 €</td><td>3 000-5 000 €</td><td>1 500-2 500 €</td></tr></tbody></table><h3 id="depenses" tabindex="-1">Dépenses <a class="header-anchor" href="#depenses" aria-label="Permalink to &quot;Dépenses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Catégorie</th><th>Coût</th><th>Remarques</th></tr></thead><tbody><tr><td><strong>Location de salle</strong></td><td>500-1 000 €</td><td>Tarif week-end</td></tr><tr><td><strong>Hébergement</strong></td><td>40-60 €/personne/nuit</td><td>Chambres partagées</td></tr><tr><td><strong>Repas</strong></td><td>30-40 €/personne/jour</td><td>6 repas</td></tr><tr><td><strong>Personnel</strong></td><td>500-1 000 €</td><td>MPC + entraîneurs</td></tr><tr><td><strong>Matériel</strong></td><td>100-200 €</td><td>Fiches d&#39;exercices, fournitures</td></tr><tr><td><strong>Prix</strong></td><td>100-200 €</td><td>Objets de reconnaissance</td></tr></tbody></table><p><strong>Total par personne :</strong> 120-180 € <strong>Marge :</strong> 30 à 70 €/personne (ou seuil de rentabilité pour le développement communautaire)</p><h2 id="indicateurs-de-succes" tabindex="-1">Indicateurs de succès <a class="header-anchor" href="#indicateurs-de-succes" aria-label="Permalink to &quot;Indicateurs de succès&quot;">​</a></h2><h3 id="indicateurs-immediats" tabindex="-1">Indicateurs immédiats <a class="header-anchor" href="#indicateurs-immediats" aria-label="Permalink to &quot;Indicateurs immédiats&quot;">​</a></h3><ul><li>[ ] Score de sécurité psychologique (1-10 moyenne &gt;7)</li><li>[ ] Taux de participation (&gt;80 % de partage actif)</li><li>[ ] Taux de remplissage (&gt;90% séjour complet le week-end)</li><li>[ ] Score de satisfaction (1-10 moyenne &gt;8)</li></ul><h3 id="indicateurs-a-long-terme" tabindex="-1">Indicateurs à long terme <a class="header-anchor" href="#indicateurs-a-long-terme" aria-label="Permalink to &quot;Indicateurs à long terme&quot;">​</a></h3><ul><li>[ ] Changement de comportement (utilisation d&#39;outils en compétition)</li><li>[ ] Amélioration des performances (auto-déclarée)</li><li>[ ] Création de liens communautaires (rester en contact)</li><li>[ ] Recommandations (recommander à d&#39;autres personnes)</li></ul><h2 id="erreurs-courantes-a-eviter" tabindex="-1">Erreurs courantes à éviter <a class="header-anchor" href="#erreurs-courantes-a-eviter" aria-label="Permalink to &quot;Erreurs courantes à éviter&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Pièges</p><p><strong>1. Trop de contenu</strong></p><ul><li>J&#39;essaie de tout couvrir</li><li><strong>Correction :</strong> Privilégiez la profondeur à l&#39;étendue</li></ul><p><strong>2. Omettre la réflexion</strong></p><ul><li>Se précipiter vers l&#39;activité suivante</li><li><strong>Correction :</strong> Temps de traitement intégré</li></ul><p><strong>3. Négliger la résistance</strong></p><ul><li>Surmonter le scepticisme</li><li><strong>Solution :</strong> Abordez le problème directement avec l’aïkido verbal.</li></ul><p><strong>4. Encadrement technique pendant la théorie</strong></p><ul><li>Mélanger les rôles</li><li><strong>Correction :</strong> Clarifier les limites entre le MPC et l&#39;entraîneur technique</li></ul><p><strong>5. Aucun suivi</strong> Le week-end se termine, l&#39;apprentissage s&#39;arrête</p><ul><li><strong>Correction :</strong> Planifier les points de contact après le camp</li></ul></div><h2 id="ressources" tabindex="-1">Ressources <a class="header-anchor" href="#ressources" aria-label="Permalink to &quot;Ressources&quot;">​</a></h2><h3 id="de-ce-site" tabindex="-1">De ce site <a class="header-anchor" href="#de-ce-site" aria-label="Permalink to &quot;De ce site&quot;">​</a></h3><ul><li><a href="./workshop">Guide d&#39;atelier</a> - Protocoles d&#39;animation détaillés</li><li><a href="./training-session">Guide de la séance d&#39;entraînement</a> - Pour la pratique continue</li><li><a href="./education/nutrition/">Nutrition</a> - Protocoles du jour de compétition</li><li><a href="./education/mental-strength/">Force mentale</a> - Concepts de jeu intérieur</li><li><a href="./education/mindfulness/">Pleine conscience</a> - Techniques de présence</li><li><a href="./education/tactics/">Tactiques</a> - Pensée stratégique</li></ul><h3 id="lectures-recommandees" tabindex="-1">Lectures recommandées <a class="header-anchor" href="#lectures-recommandees" aria-label="Permalink to &quot;Lectures recommandées&quot;">​</a></h3><ul><li><em>Le Jeu intérieur du tennis</em> par Timothy Gallwey</li><li><em>Mindset</em> de Carol Dweck</li><li><em>L&#39;Organisation intrépide</em> par Amy Edmondson</li></ul>',141))])}]]);export{d as __pageData,p as default};
